args.new_string:
import { revalidatePath } from 'next/cache';

// Simulated database - in a real app, this would be a database call
let notificationPreference = false;

async function toggleNotification() {
  'use server';

  // Toggle the preference
  notificationPreference = !notificationPreference;

  // Revalidate the current page to show updated preference
  revalidatePath('/');
}

export default function Home() {
  return (
    <main>
      <h1>Settings</h1>
      <div style={{ marginTop: '20px' }}>
        <p>
          Notifications: <strong>{notificationPreference ? 'ON' : 'OFF'}</strong>
        </p>
        <form action={toggleNotification}>
          <button type="submit">
            Toggle Notifications
          </button>
        </form>
      </div>
    </main>
  );
}

